using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;namespace OperationsRequests.Pages.Admin;[Authorize(Roles="PlatformAdmin")]public class UsersModel(ApplicationDbContext db,UserManager<ApplicationUser> users):PageModel{public List<ApplicationUser> Users{get;set;}=[];public List<Country> Countries{get;set;}=[];public List<Territory> Territories{get;set;}=[];public List<Site> Sites{get;set;}=[];[BindProperty]public UserInput Input{get;set;}=new();public sealed class UserInput{public string Email{get;set;}="";public string DisplayName{get;set;}="";public string Password{get;set;}="";public string Role{get;set;}=Roles.StaffMember;public int? CountryId{get;set;}public int? TerritoryId{get;set;}public int? SiteId{get;set;}}public async Task OnGetAsync()=>await Load();public async Task<IActionResult> OnPostCreateAsync(){await Load();var site=Input.SiteId is null?null:await db.Sites.Include(x=>x.Territory).SingleOrDefaultAsync(x=>x.Id==Input.SiteId);var territory=Input.TerritoryId is null?null:await db.Territories.SingleOrDefaultAsync(x=>x.Id==Input.TerritoryId);var ok=Input.Role switch{Roles.PlatformAdmin=>Input.CountryId is null&&Input.TerritoryId is null&&Input.SiteId is null,Roles.CountryOpsManager=>Input.CountryId is not null&&Input.TerritoryId is null&&Input.SiteId is null,Roles.TerritoryManager=>territory is not null&&territory.CountryId==Input.CountryId&&Input.SiteId is null,Roles.SiteManager or Roles.StaffMember=>site is not null&&site.TerritoryId==Input.TerritoryId&&site.Territory.CountryId==Input.CountryId,_=>false};if(!ok||!Roles.All.Contains(Input.Role)){ModelState.AddModelError("","Invalid role/organisation assignment.");return Page();}var u=new ApplicationUser{UserName=Input.Email,Email=Input.Email,EmailConfirmed=true,DisplayName=Input.DisplayName,CountryId=Input.CountryId,TerritoryId=Input.TerritoryId,SiteId=Input.SiteId};var result=await users.CreateAsync(u,Input.Password);if(!result.Succeeded){foreach(var e in result.Errors)ModelState.AddModelError("",e.Description);return Page();}await users.AddToRoleAsync(u,Input.Role);db.AuditEvents.Add(new AuditEvent{Action="UserCreated",ActorId=(await users.GetUserAsync(User))!.Id,ActorName="Platform Admin",Note=$"{u.Email} / {Input.Role}"});await db.SaveChangesAsync();return RedirectToPage();}public async Task<IActionResult> OnPostToggleAsync(string id){var u=await users.FindByIdAsync(id);if(u is null)return NotFound();u.IsActive=!u.IsActive;if(!u.IsActive)await users.UpdateSecurityStampAsync(u);await users.UpdateAsync(u);db.AuditEvents.Add(new AuditEvent{Action=u.IsActive?"UserActivated":"UserDeactivated",ActorId=(await users.GetUserAsync(User))!.Id,ActorName="Platform Admin",Note=u.Email});await db.SaveChangesAsync();return RedirectToPage();}async Task Load(){Users=await users.Users.OrderBy(x=>x.Email).ToListAsync();Countries=await db.Countries.OrderBy(x=>x.Name).ToListAsync();Territories=await db.Territories.OrderBy(x=>x.Name).ToListAsync();Sites=await db.Sites.Include(x=>x.Territory).ThenInclude(x=>x.Country).OrderBy(x=>x.Name).ToListAsync();}}

